cat > /tmp/deps.py <<'EOF'
import re, os, glob
root = '/w'
report = {}
for py in sorted(glob.glob(root + '/02-backend/**/pyproject.toml', recursive=True) + glob.glob(root + '/03-shared-services/*/pyproject.toml')):
    base = os.path.dirname(py)
    svc = os.path.relpath(base, root)
    txt = open(py).read()
    paths = re.findall(r'\[tool\.uv\.sources\.([\w\-]+)\]\s*\n\s*path = "([^"]+)"', txt)
    if not paths:
        continue
    outside = []
    for name, p in paths:
        target = os.path.normpath(os.path.join(base, p))
        rel = os.path.relpath(target, base)
        if rel.startswith('..'):
            outside.append((name, p, target.replace(root+'/','')))
    if outside:
        report[svc] = outside
for k, v in report.items():
    print(k)
    for name, p, t in v:
        print(f"   {name}: {p}  ->  {t}")
EOF
